"use client";
import React, { useState } from "react";
import Providers from "./providers";
import TimerTable from "../components/timers/TimerTable";
import TimerModal from "../components/timers/TimerModal";
import DeleteTimerModal from "../components/timers/DeleteTimerModal";
import EmptyStateView from "../components/common/EmptyStateView";
import LoadingState from "../components/common/LoadingState";
import { Toast } from "@shopify/polaris";
import { PlusIcon } from "@shopify/polaris-icons";
import useTimers from "../hooks/useTimers";
import { formatDateTime } from "../utils/dateUtils";

export default function Home() {
  const {
    timers,
    loading,
    fetchTimers,
    createTimer,
    updateTimer,
    deleteTimer,
  } = useTimers();
  const [searchQuery, setSearchQuery] = useState("");
  const [modalActive, setModalActive] = useState(false);
  const [selectedTimer, setSelectedTimer] = useState<{
    id?: string;
    _id?: string;
  } | null>(null);
  const [toastActive, setToastActive] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [deleteModalActive, setDeleteModalActive] = useState(false);
  const [timerToDelete, setTimerToDelete] = useState<{
    id?: string;
    _id?: string;
  } | null>(null);

  const showToast = (message: string) => {
    setToastMessage(message);
    setToastActive(true);
  };

  const handleCreateTimer = () => {
    setSelectedTimer(null);
    setModalActive(true);
  };

  const handleEditTimer = (timer: any) => {
    setSelectedTimer(timer);
    setModalActive(true);
  };

  const handleDeleteClick = (timer: any) => {
    setTimerToDelete(timer);
    setDeleteModalActive(true);
  };

  const handleDeleteConfirm = async () => {
    if (!timerToDelete) return;
    try {
      await deleteTimer(timerToDelete.id || timerToDelete._id);
      showToast("Timer deleted successfully");
      fetchTimers();
    } catch {
      showToast("Failed to delete timer");
    } finally {
      setDeleteModalActive(false);
      setTimerToDelete(null);
    }
  };

  const handleSaveTimer = async (payload: any) => {
    try {
      if (selectedTimer) {
        await updateTimer(selectedTimer.id || selectedTimer._id, payload);
        showToast("Timer updated successfully");
      } else {
        await createTimer(payload);
        showToast("Timer created successfully");
      }
      fetchTimers();
    } catch {
      showToast("Failed to save timer");
      throw new Error("Failed to save timer");
    }
  };

  const filteredTimers = timers.filter((timer: any) =>
    timer.timerName?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <Providers>
      <div className="min-h-screen bg-gray-50">
        <header className="bg-white shadow">
          <div className="max-w-7xl mx-auto py-6 px-4 sm:px-6 lg:px-8">
            <h1 className="text-3xl font-bold text-gray-900">
              Countdown Timer Manager
            </h1>
            <p className="text-gray-600">
              Create and manage countdown timers for your promotions
            </p>
            <button
              className="mt-4 inline-flex items-center px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-md hover:bg-blue-700 focus:outline-none"
              onClick={handleCreateTimer}
            >
              <PlusIcon className="w-5 h-5 mr-2 text-blue-800" />
              Create Timer
            </button>
          </div>
        </header>

        <main className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
          <div className="bg-white shadow rounded-lg p-6">
            <div className="mb-4">
              <input
                type="text"
                placeholder="Search timers"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500"
              />
            </div>
            {loading ? (
              <LoadingState />
            ) : filteredTimers.length === 0 ? (
              <EmptyStateView onAction={handleCreateTimer} />
            ) : (
              <TimerTable
                timers={filteredTimers.map((t: any) => ({
                  ...t,
                  startDateTime: formatDateTime(t.startDateTime),
                  endDateTime: formatDateTime(t.endDateTime),
                }))}
                onEdit={handleEditTimer}
                onDelete={handleDeleteClick}
              />
            )}
          </div>
        </main>

        <TimerModal
          active={modalActive}
          timer={selectedTimer}
          onClose={() => setModalActive(false)}
          onSave={handleSaveTimer}
        />

        <DeleteTimerModal
          open={deleteModalActive}
          timer={timerToDelete}
          onClose={() => setDeleteModalActive(false)}
          onDelete={handleDeleteConfirm}
        />

        {toastActive && (
          <Toast
            content={toastMessage}
            onDismiss={() => setToastActive(false)}
            duration={3000}
          />
        )}
      </div>
    </Providers>
  );
}
